import React, { useState, useEffect } from 'react';
import { Link, NavLink, useNavigate, useLocation } from 'react-router-dom';
import logoImage from '../../assets/icons/logoSJ 24th 3 2024.svg';
import darkModeIcon from '../../assets/icons/darkmode.jpg';


const Header = ({ categories, currentFilter, onFilterChange }) => {
  const [menuOpen, setMenuOpen] = useState(false);
  const navigate = useNavigate();
  const location = useLocation();
  const [darkMode, setDarkMode] = useState(() => {
    // Get the dark mode value from local storage or default to false
    const savedMode = localStorage.getItem('darkMode');
    return savedMode === 'true' ;
  });

  useEffect(() => {
    // Apply the dark mode class based on the state
    document.documentElement.classList.toggle('dark', darkMode);
    document.documentElement.style.transition = 'background-color 500ms';
  }, [darkMode]);

  const toggleMenu = () => {
    setMenuOpen(!menuOpen);
    if (!menuOpen) {
      // Disable scrolling
      document.body.classList.add('overflow-hidden');
    } else {
      // Enable scrolling
      document.body.classList.remove('overflow-hidden');
    }
  };
    const closeMenu = () => setMenuOpen(false);
  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);
    localStorage.setItem('darkMode', newDarkMode.toString());
  };

  // Function to handle work button click
  const handleWorkClick = (e) => {
    e.preventDefault();
    
    if (location.pathname === '/') {
      // If already on home page, scroll to work section
      const workSection = window.innerHeight; // One viewport height down
      window.scrollTo({
        top: workSection,
        behavior: 'smooth'
      });
    } else {
      // If on different page, navigate to home and then scroll
      navigate('/');
      // Clear any saved scroll position to ensure we start from top
      localStorage.removeItem('homePageScrollPosition');
      
      // Wait for navigation and page load, then scroll
      setTimeout(() => {
        const workSection = window.innerHeight;
        window.scrollTo({
          top: workSection,
          behavior: 'smooth'
        });
      }, 300);
    }
  };

  return (
    <header className={`lg:flex lg:justify-between z-50 lg:items-center ${darkMode ? 'dark' : ''}`}>
      {/* Header Background */}
      <div className="fixed top-0 left-0 w-full h-18 bg-white dark:bg-black z-30 transition-colors duration-500"></div>
  <div className="container mx-auto flex justify-between items-center lg:mx-0 z-50">
    <div className="flex items-center space-x-6 z-40">
      <a href="/" target="_blank" rel="noopener noreferrer">
        <img src={logoImage} alt="Logo" className="fixed top-6 left-6 dark:invert w-12 h-6" data-cursor="pointer" />
      </a>
    </div>

    {/* Dark Mode Icon */}
    {/* <img 
      src={darkModeIcon} 
      alt="Toggle Dark Mode" 
      className="fixed top-6 right-18 lg:right-6 z-50 w-6 h-6 dark:invert transition-colors duration-500 clickable"
      data-cursor="pointer"
      onClick={toggleDarkMode}
    /> */}
    {/* Mobile Menu Button */}
    <button 
      onClick={toggleMenu} 
      className="lg:hidden fixed top-6 right-6 z-50 clickable"
      data-cursor="pointer"
    >
      <div className="bg-black dark:bg-white w-6 h-6"></div>
    </button>

    {/* Mobile Navigation */}
    <nav className={`fixed inset-0 bg-black bg-opacity-50 backdrop-blur
      ${menuOpen ? 'flex' : 'hidden'} 
      flex-col items-center justify-center space-y-6 lg:hidden z-40
      transition-all duration-500 ease-in-out`}>



      <Link to="/About" onClick={closeMenu} className="bg-black dark:bg-white text-white dark:text-black text-center min-w-[290px] px-3 h-6 leading-6 text-2xl clickable" data-cursor="pointer">
        ABOUT
      </Link>
   
      <a>        
      </a>
      {/* Filter Categories for Mobile */}
      {categories.map(category => (
        <a
          key={category}
          href="#"
          className="bg-black text-white dark:bg-white dark:text-black px-3 h-6 leading-6 text-center text-xl min-w-[290px] clickable"
          data-cursor="pointer"
          onClick={() => { onFilterChange(category); closeMenu(); }}
        >
          {category}
        </a>
      ))}



    </nav>

    {/* Large Screen Navigation */}
    <nav className="hidden lg:flex space-x-6 fixed top-6 ">

   
      <NavLink to="/"  className="fixed left-[96px] text-black dark:text-white px-0 text-[14px] leading-6 h-6 clickable" data-cursor="pointer">
      SHAREEF JASIM
        </NavLink>
    
      <NavLink to="About" className="fixed right-[24px] text-black dark:text-white px-0 text-[14px] leading-6 h-6 clickable" data-cursor="pointer">
      ABOUT
        </NavLink>
        <a href="#" onClick={handleWorkClick} className="fixed right-[104px] text-black dark:text-white px-0 text-[14px] leading-6 h-6 clickable" data-cursor="pointer">
      WORK
        </a>
    </nav>
  </div>
</header>


  );
};

export default Header;
