import React, { useEffect, useRef, useState, useMemo } from "react";
import { motion, AnimatePresence } from "framer-motion";
import ProjectSquare from "./ProjectSquare";

function ProjectBoard({ projects, selectedCategory, onSquareClick }) {
  const gridRef = useRef(null);
  const [cellSize, setCellSize] = useState(0);
  const [currentLayout, setCurrentLayout] = useState([]);
  const [targetLayout, setTargetLayout] = useState([]);
  const [animationPhase, setAnimationPhase] = useState('idle'); // 'idle', 'fadeOut', 'move', 'fadeIn'
  const [incomingIds, setIncomingIds] = useState([]); // ids that will fade in after move
  const [hoveredItemKey, setHoveredItemKey] = useState(null);

  // Calculate cell size based on container width
  useEffect(() => {
    const calculateCellSize = () => {
      if (gridRef.current) {
        const containerWidth = gridRef.current.clientWidth;
        const gapSize = 72; // gap size in pixels
        const columnsCount = 6; // number of columns
        const totalGapWidth = (columnsCount - 1) * gapSize;
        const calculatedCellSize = (containerWidth - totalGapWidth) / columnsCount;
        setCellSize(calculatedCellSize);
      }
    };

    calculateCellSize();
    window.addEventListener("resize", calculateCellSize);
    return () => window.removeEventListener("resize", calculateCellSize);
  }, []);

  // Helpers for grid spans
  const getColSpan = size => {
    switch (size) {
      case 'large': return 'col-span-3';
      case 'medium': return 'col-span-2';
      default: return 'col-span-1';
    }
  };
  const getRowSpan = size => {
    switch (size) {
      case 'large': return 'row-span-3';
      case 'medium': return 'row-span-2';
      default: return 'row-span-1';
    }
  };

  // Create stable empty spaces that don't cause repositioning chaos
  const createLayoutWithSpaces = (projectArray) => {
    if (projectArray.length === 0) return [];
    
    const result = [...projectArray];
    const emptySpaceChance = 0.25; // Reduced chance for stability
    const maxEmptySpaces = Math.floor(projectArray.length * 0.3); // Reduced max for stability
    let emptySpacesAdded = 0;
    
    const emptySpaceSizes = ['small', 'medium'];
    
    // Create deterministic empty spaces based on project IDs for consistency
    for (let i = 0; i < result.length && emptySpacesAdded < maxEmptySpaces; i++) {
      const project = result[i];
      if (project.isEmpty) continue;
      
      // Use project ID hash for consistent placement
      const projectIdHash = project.id || project.targetUrl || project.title || '';
      const hash = projectIdHash.split('').reduce((a, b) => a + b.charCodeAt(0), 0);
      
      if ((hash % 100) < (emptySpaceChance * 100)) {
        const sizeIndex = hash % emptySpaceSizes.length;
        const randomSize = emptySpaceSizes[sizeIndex];
        
        const emptySpace = {
          isEmpty: true,
          id: `empty-${projectIdHash}-${i}`, // Stable ID
          projectCardSize: randomSize,
          targetUrl: null,
          title: `Empty Space ${emptySpacesAdded}`,
          stableKey: `empty-${projectIdHash}-${i}` // For tracking
        };
        
        // Insert after current project for predictable layout
        result.splice(i + 1, 0, emptySpace);
        emptySpacesAdded++;
        i++; // Skip the newly inserted empty space
      }
    }
    
    return result;
  };

  // Calculate the new assembly layout first (step 1)
  const newAssemblyLayout = useMemo(() => {
    return createLayoutWithSpaces(projects);
  }, [projects]);

  // Build move layout: target order with placeholders for incoming items
  const buildMoveLayout = (prevLayout, nextLayout) => {
    const prevIds = new Set(prevLayout.map(i => i.id || i.targetUrl || i.title));
    const nextIds = nextLayout.map(i => i.id || i.targetUrl || i.title);
    const incoming = [];
    const moveLayout = nextLayout.map((item, idx) => {
      const key = item.id || item.targetUrl || item.title;
      if (!prevIds.has(key)) {
        incoming.push(key);
        return {
          ...item,
          isPlaceholder: true,
          stableKey: item.stableKey || `placeholder-${key}-${idx}`
        };
      }
      return item;
    });
    return { moveLayout, incoming };
  };

  // Animation system: determine → fade out → move (with placeholders) → fade in
  useEffect(() => {
    if (currentLayout.length === 0) {
      // Initial load - no animation needed
      setCurrentLayout(newAssemblyLayout);
      setTargetLayout(newAssemblyLayout);
      setAnimationPhase('idle');
      return;
    }

    // Check if layout actually changed
    const currentIds = currentLayout.map(item => item.id || item.targetUrl || item.title).join(',');
    const newIds = newAssemblyLayout.map(item => item.id || item.targetUrl || item.title).join(',');
    
    if (currentIds === newIds) {
      return; // No change needed
    }

    // Step 1: Determine new assembly (already done in useMemo)
    setTargetLayout(newAssemblyLayout);

    // Step 2: Start animation sequence
    setAnimationPhase('fadeOut');
    
    // Step 3: Fade out unwanted items (300ms)
    setTimeout(() => {
      // Build move layout with placeholders to reserve space and avoid row reflow
      const { moveLayout, incoming } = buildMoveLayout(currentLayout, newAssemblyLayout);
      setIncomingIds(incoming);
      setCurrentLayout(moveLayout); // triggers smooth move to final positions
      setAnimationPhase('move');

      // Step 4: After move, replace placeholders with real items (same keys) and fade them in
      setTimeout(() => {
        setAnimationPhase('fadeIn');
        setCurrentLayout(prev => {
          const nextById = new Map(newAssemblyLayout.map(it => [it.id || it.targetUrl || it.title, it]));
          return prev.map(it => {
            if (it.isPlaceholder) {
              const key = it.id || it.targetUrl || it.title;
              const real = nextById.get(key) || it;
              return { ...real, stableKey: it.stableKey, isEntering: true };
            }
            return it;
          });
        });

        // Step 5: Finish
        setTimeout(() => {
          setAnimationPhase('idle');
          setIncomingIds([]);
          // Clear isEntering flags and fully sync with target
          setCurrentLayout(newAssemblyLayout);
        }, 300);
      }, 400);
    }, 300);
    
  }, [newAssemblyLayout]);

  // Phase-specific animation variants (all ease in-out)
  const cardVariants = {
    visible: {
      opacity: 1,
      scale: 1,
      transition: {
        duration: 0.5,
        ease: 'easeInOut'
      }
    },
    ghost: {
      opacity: 0.,
      scale: 1,
      transition: {
        duration: 0.4,
        ease: 'easeInOut'
      }
    },
    fadeOut: {
      opacity: 0,
      scale: 0.95,
      transition: {
        duration: 0.4,
        ease: 'easeInOut'
      }
    },
    moving: {
      opacity: 1,
      scale: 1,
      transition: {
        duration: 0.5,
        ease: 'easeInOut',
        layout: {
          duration: 0.5,
          ease: 'easeInOut'
        }
      }
    },
    fadeIn: {
      opacity: 1,
      scale: 1,
      transition: {
        duration: 0.4,
        ease: 'easeInOut',
        delay: 0
      }
    },
    hidden: {
      opacity: 0,
      scale: 0.95
    }
  };

  return (
    <div className="px-[72px] pt-12 pb-18 max-w-[1920px] mx-auto min-h-screen">
      <motion.div
        ref={gridRef}
        className="grid grid-cols-6 gap-[72px] min-h-[80vh] justify-items-start"
        style={{
          gridAutoFlow: 'row',
          gridAutoRows: `${cellSize}px`
        }}
        layout
      >
        <AnimatePresence mode="popLayout" initial={false}>
          {currentLayout.map((item, index) => {
            const itemKey = item.stableKey || item.id || item.targetUrl || item.title || `item-${index}`;
            
            // Determine animation state based on phase and item status
            const getAnimationState = () => {
              // Check if item exists in current vs target layouts
              const existsInCurrent = currentLayout.some(i => 
                (i.id || i.targetUrl || i.title) === (item.id || item.targetUrl || item.title)
              );
              const existsInTarget = targetLayout.some(i => 
                (i.id || i.targetUrl || i.title) === (item.id || item.targetUrl || item.title)
              );
              
              // Find current and target positions to check if item needs to move
              const currentIndex = currentLayout.findIndex(i => 
                (i.id || i.targetUrl || i.title) === (item.id || item.targetUrl || item.title)
              );
              const targetIndex = targetLayout.findIndex(i => 
                (i.id || i.targetUrl || i.title) === (item.id || item.targetUrl || item.title)
              );
              
              const needsToMove = existsInCurrent && existsInTarget && currentIndex !== targetIndex;
              
              if (item.isEntering) {
                return 'fadeIn';
              }
              if (animationPhase === 'fadeOut' && !existsInTarget) {
                return 'fadeOut'; // Item should fade out
              } else if (animationPhase === 'move' && needsToMove) {
                return 'moving'; // Item should move to new position
              } else if (animationPhase === 'fadeIn' && existsInTarget && !existsInCurrent) {
                return 'fadeIn'; // New item should fade in
              } else if (existsInTarget) {
                return 'visible'; // Item should stay visible (no movement needed)
              } else {
                return 'hidden'; // Item should be hidden
              }
            };
            
            // Handle empty spaces and placeholders
            if (item.isEmpty || item.isPlaceholder) {
              return (
                <motion.div
                  key={itemKey}
                  className={`${getColSpan(item.projectCardSize)} ${getRowSpan(item.projectCardSize)} relative w-full ${item.isPlaceholder ? 'pointer-events-none' : ''}`}
                  layout="position"
                  variants={cardVariants}
                  initial={item.isPlaceholder ? 'ghost' : 'visible'}
                  animate={item.isPlaceholder 
                    ? (animationPhase === 'move' ? 'ghost' : (animationPhase === 'fadeIn' ? 'fadeOut' : 'hidden'))
                    : getAnimationState()}
                  exit="fadeOut"
                  style={item.isPlaceholder ? { zIndex: 0 } : undefined}
                >
                  <div className={`w-full h-full ${item.isPlaceholder ? 'bg-transparent' : 'bg-transparent'}`} />
                </motion.div>
              );
            }
            
            // Handle regular projects
            const projectKey = item.id || item.targetUrl || item.title || `project-${index}`;
            const isOtherHovered = hoveredItemKey && hoveredItemKey !== itemKey;

            return (
              <motion.div
                key={projectKey}
                className={`${getColSpan(item.projectCardSize)} ${getRowSpan(item.projectCardSize)} relative w-full`}
                layout="position"
                variants={cardVariants}
                initial={item.isEntering ? 'hidden' : 'visible'}
                animate={getAnimationState()}
                exit="fadeOut"
                style={item.isEntering ? { zIndex: 2 } : undefined}
                onMouseEnter={() => setHoveredItemKey(itemKey)}
                onMouseLeave={() => setHoveredItemKey(null)}
              >
                <ProjectSquare
                  project={item}
                  isSelected={
                    selectedCategory !== "All Work" &&
                    item.categories && item.categories.includes(selectedCategory)
                  }
                  onClick={() => onSquareClick({ project: item, id: index })}
                />
                
                {/* White overlay for hover blur effect */}
                {isOtherHovered && (
                  <div className="absolute inset-0 bg-white bg-opacity-0 pointer-events-none transition-opacity duration-300" />
                )}
              </motion.div>
            );
          })}
          
          {/* New items fade-in is handled by placeholders swapping to real items above. */}
        </AnimatePresence>
      </motion.div>
    </div>
  );
}

export default ProjectBoard;