// /src/components/ProjectSquare.js
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import GLTFViewer from "../common/GLTFViewer"; // adjust path if needed

/**
 * You now have FULL, SEPARATE control over sizing/cover behavior for:
 * - Background media (usually the hover media)
 * - Foreground media (original media)
 * in BOTH states: non-hover (base) and hover.
 *
 * Tweak the Tailwind classes in `defaultStyles` or pass overrides via:
 *   project.styleOverrides = {
 *     fg: { base: { img, model }, hover: { img, model } },
 *     bg: { base: { img, model }, hover: { img, model } }
 *   }
 */
const defaultStyles = {
  // Foreground == original media layer (on top when NOT hovered)
  fg: {
    base: {
      img: "absolute inset-0 flex items-center justify-center [&>img]:w-[90%] [&>img]:h-[90%] [&>img]:object-contain",
      model: "absolute inset-0 [&>div]:w-full [&>div]:h-full", // GLTF container fills
    },
    hover: {
      // When hovered, we typically HIDE fg; class still applied pre-transition if you want different sizing
      img: "absolute inset-0 flex items-center justify-center [&>img]:w-[90%] [&>img]:h-[90%] [&>img]:object-contain",
      model: "absolute inset-0 [&>div]:w-full [&>div]:h-full",
    },
  },

  // Background == hover media layer (visible behind blur in NON-hover; fully visible on hover)
  bg: {
    base: {
      // Not hovered → show the would-be hover media blurred/dimmed underneath
      img: "absolute inset-0 flex items-center justify-center [&>img]:w-full [&>img]:h-full [&>img]:object-cover",
      model: "absolute inset-0 [&>div]:w-full [&>div]:h-full",
    },
    hover: {
      // Hovered → unblur/shine the hover media (maybe switch to contain, etc.)
      img: "absolute inset-0 flex items-center justify-center [&>img]:w-full [&>img]:h-full [&>img]:object-cover",
      model: "absolute inset-0 [&>div]:w-full [&>div]:h-full",
    },
  },
};

const ProjectSquare = ({ project, isSelected, onClick }) => {
  const navigate = useNavigate();
  const [isHovered, setIsHovered] = useState(false);

  const {
    mediaType,
    mediaSrc,
    hoverMediaSrc,
    hoverMediaType,
    invert,
    title,
    description,
    cameraType,
    cameraPosition,
    cameraLookAt,
    ambientIntensity,
    directionalLightPosition,
    directionalLightTarget,
    directionalLightIntensity,
    allowPan,
    targetUrl,

    // Optional: per-card style overrides
    styleOverrides,
  } = project;

  // Merge overrides (shallow)
  const styles = mergeStyles(defaultStyles, styleOverrides);

  const handleClick = (e) => {
    if (e.button === 0 && targetUrl) navigate(targetUrl);
    if (onClick) onClick(e);
  };
  const handleContextMenu = (e) => e.preventDefault();

  // Background media (the one you want to reveal on hover)
  const bgSrc = hoverMediaSrc || mediaSrc;
  const bgType = hoverMediaType || mediaType;

  // Helpers to pick class sets based on state & type
  const pickClasses = (layer /* 'fg' | 'bg' */, type /* 'image'|'gif'|'3dmodel' */) => {
    const stateKey = isHovered ? "hover" : "base";
    const typeKey = type === "3dmodel" ? "model" : "img";
    return styles[layer][stateKey][typeKey];
  };

  const renderMediaElement = (src, type, layer) => {
    if (!src) return null;
    const wrapperClasses = pickClasses(layer, type);

    // IMAGE / GIF
    if (type === "image" || type === "gif") {
      return (
        <div className={wrapperClasses}>
          <img
            src={src}
            alt={title}
            className={`${invert ? "dark:invert-0" : ""}`}
          />
        </div>
      );
    }

    // 3D MODEL
    if (type === "3dmodel") {
      return (
        <div className={wrapperClasses}>
          <div className="w-full h-full">
            <GLTFViewer
              src={src}
              cameraType={cameraType}
              cameraPosition={cameraPosition}
              cameraLookAt={cameraLookAt}
              ambientIntensity={ambientIntensity}
              directionalLightPosition={directionalLightPosition}
              directionalLightTarget={directionalLightTarget}
              directionalLightIntensity={directionalLightIntensity}
              allowPan={allowPan}
            />
          </div>
        </div>
      );
    }

    return null;
  };

  return (
    <div
      onClick={handleClick}
      onContextMenu={handleContextMenu}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className={`relative w-full aspect-square flex items-center justify-center
        transition-all duration-300 ease-in-out cursor-none project-link bg-white`}
    >
      {/* BACKGROUND MEDIA */}
      <div
        className={`absolute inset-0 transition-all duration-300 ${
          isHovered ? "opacity-100" : "opacity-5"
        }`}
      >
        {renderMediaElement(bgSrc, bgType, "bg")}

        {/* Blur/dim overlay when NOT hovered */}
        {!isHovered && (
          <>
            <div className="absolute inset-0 pointer-events-none backdrop-blur-3xl"></div>
            <div className="absolute inset-0 pointer-events-none bg-white/0"></div>
          </>
        )}
      </div>

      {/* FOREGROUND (ORIGINAL) MEDIA */}
      <div
        className={`absolute inset-0 transition-opacity duration-500 ${
          isHovered ? "opacity-0" : "opacity-100"
        }`}
      >
        {renderMediaElement(mediaSrc, mediaType, "fg")}
      </div>

      {/* TEXT OVERLAY */}
      <div
        className={`absolute inset-0 flex items-end justify-center transition-opacity duration-300 pointer-events-none ${
          isHovered ? "opacity-100" : "opacity-0"
        }`}
      >
        <span className="text-black text-center p-1">
          <div className="text-project-card-name">{title}</div>
          {description && (
            <div className="text-project-card-description mt-1">
              {description}
            </div>
          )}
        </span>
      </div>
    </div>
  );
};

export default ProjectSquare;

/** --- utilities --- */
function mergeStyles(base, overrides) {
  if (!overrides) return base;
  const out = JSON.parse(JSON.stringify(base));
  for (const layer of ["fg", "bg"]) {
    if (!overrides[layer]) continue;
    for (const state of ["base", "hover"]) {
      if (!overrides[layer][state]) continue;
      for (const type of ["img", "model"]) {
        if (overrides[layer][state][type]) {
          out[layer][state][type] = overrides[layer][state][type];
        }
      }
    }
  }
  return out;
}
