// src/components/AnimatedSquares.js
import React, { useState, useEffect, useRef, Fragment } from 'react';
import { gsap } from 'gsap';

const AnimatedSquares = ({
  // Container margins (percentage of container)
  topMargin = 10,        // % from top edge
  bottomMargin = 10,     // % from bottom edge  
  leftMargin = 10,       // % from left edge
  rightMargin = 10,      // % from right edge
  
  // Drift distance (percentage of container)
  driftX = 15,           // % of container width for horizontal drift
  driftY = 15,           // % of container height for vertical drift
  
  // Square properties
  count = 10,            // number of squares
  minSize = 5,           // % of container width
  maxSize = 15,          // % of container width
  
  // Animation timing
  minDuration = 1,       // seconds
  maxDuration = 3,       // seconds
  
  // Distribution bias
  centerBias = 0.6,      // 0.5 = random, 1.0 = fully centered
}) => {
  // Get colors from CSS custom properties (defined in App.css)
  const getSquareColors = () => {
    if (typeof window !== 'undefined') {
      const root = getComputedStyle(document.documentElement);
      return [
        root.getPropertyValue('--color-square-1').trim(),
        root.getPropertyValue('--color-square-2').trim(),
        root.getPropertyValue('--color-square-3').trim(),
        root.getPropertyValue('--color-square-4').trim(),
        root.getPropertyValue('--color-square-5').trim(),
        root.getPropertyValue('--color-square-6').trim(),
        root.getPropertyValue('--color-square-7').trim(),
        root.getPropertyValue('--color-square-8').trim(),
      ].filter(color => color && color !== ''); // Filter out empty values
    }
    // Fallback colors for SSR or if CSS variables aren't available
    return [
      '#0B0F19', '#6B7280', '#9CA3AF', '#334155',
      '#475569', '#64748B', '#94A3B8', '#CBD5E1'
    ];
  };

  const containerRef = useRef(null);
  const [containerWidth, setContainerWidth] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);
  
  // Generate square properties once and store them
  const [squares, setSquares] = useState([]);

  // Recalculate squares when count, sizes, or container dimensions change
  useEffect(() => {
    if (!containerRef.current || containerWidth === 0 || containerHeight === 0) {
      return;
    }

    const colors = getSquareColors();
    const newSquares = Array.from({ length: count }, (_, i) => {
      // Size as percentage of container width (calculate first for positioning)
      // Now sizePct will always refer to a percentage of the container's *width*
      const sizePct = minSize + Math.random() * (maxSize - minSize);
      const squareSizePx = (sizePct / 100) * containerWidth; // Absolute pixel size for square

      const halfSizePx = squareSizePx / 2; // Half size for center-based calculations

      // Calculate available area after margins AND accounting for square size
      // This ensures the CENTER of the square stays within bounds
      // All calculations now use pixels
      const availableTopPx = containerHeight - (topMargin / 100) * containerHeight - (bottomMargin / 100) * containerHeight - squareSizePx;
      const availableLeftPx = containerWidth - (leftMargin / 100) * containerWidth - (rightMargin / 100) * containerWidth - squareSizePx;

      // Create distribution that favors the center
      const topRandom = Math.random();
      const leftRandom = Math.random();

      // Apply center bias: values closer to 0.5 are more likely
      const topBiased = 0.5 + (topRandom - 0.5) * centerBias;
      const leftBiased = 0.5 + (leftRandom - 0.5) * centerBias;

      // Position the center within available area, then offset by half size for top-left positioning
      const centerTopPx = (topMargin / 100) * containerHeight + halfSizePx + topBiased * availableTopPx;
      const centerLeftPx = (leftMargin / 100) * containerWidth + halfSizePx + leftBiased * availableLeftPx;

      // Convert center position to top-left position for CSS
      const topPx = centerTopPx - halfSizePx;
      const leftPx = centerLeftPx - halfSizePx;
      
      // Calculate maximum drift based on center position to keep square fully in bounds
      const maxDriftXFromCenter = Math.min(
        centerLeftPx - (leftMargin / 100) * containerWidth - halfSizePx,  // Distance to left edge
        (containerWidth - (rightMargin / 100) * containerWidth - halfSizePx) - centerLeftPx  // Distance to right edge
      );
      const maxDriftYFromCenter = Math.min(
        centerTopPx - (topMargin / 100) * containerHeight - halfSizePx,   // Distance to top edge
        (containerHeight - (bottomMargin / 100) * containerHeight - halfSizePx) - centerTopPx  // Distance to bottom edge
      );

      // Limit drift to keep square fully within bounds, as percentage of container
      const actualDriftX = Math.min((driftX / 100) * containerWidth, maxDriftXFromCenter);
      const actualDriftY = Math.min((driftY / 100) * containerHeight, maxDriftYFromCenter);
      
      // Drift distances in pixels
      const driftXPx = (Math.random() * 2 - 1) * actualDriftX;
      const driftYPx = (Math.random() * 2 - 1) * actualDriftY;

      const delay = Math.random() * maxDuration;
      const duration = Math.random() * (maxDuration - minDuration) + minDuration;

      // Sequential z-index for consistent layering
      const zIndex = i + 5;

      // Pick a random color from our palette
      const color = colors[Math.floor(Math.random() * colors.length)];

      return { 
        id: i, 
        topPx, 
        leftPx, 
        squareSizePx, 
        driftXPx, 
        driftYPx, 
        delay, 
        duration, 
        zIndex, 
        color,
        centerTopPx,
        centerLeftPx,
        actualDriftX,
        actualDriftY
      };
    });
    setSquares(newSquares);
  }, [count, minSize, maxSize, topMargin, bottomMargin, leftMargin, rightMargin, driftX, driftY, minDuration, maxDuration, centerBias, containerWidth, containerHeight]);

  // Set up resize observer for container
  useEffect(() => {
    const handleResize = () => {
      if (containerRef.current) {
        setContainerWidth(containerRef.current.offsetWidth);
        setContainerHeight(containerRef.current.offsetHeight);
      }
    };

    // Initial size
    handleResize();

    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('resize', handleResize);
    };
  }, []); // Empty dependency array means this runs once on mount and cleans up on unmount

  // Expert's approach: Use GSAP for animations instead of Framer Motion
  useEffect(() => {
    if (!containerRef.current || squares.length === 0) return;
    
    // Clear existing animations to prevent conflicts on re-render
    gsap.killTweensOf(containerRef.current.querySelectorAll('[data-square-id]'));

    squares.forEach((square) => {
      const element = containerRef.current.querySelector(`[data-square-id="${square.id}"]`);
      if (element) {
        
        // Use the pre-calculated pixel drift values directly
        const driftXPx = square.driftXPx;
        const driftYPx = square.driftYPx;
        
        // Expert's GSAP animation pattern - using timeline for complex sequences
        const tl = gsap.timeline({ 
          repeat: -1, 
          yoyo: true, 
          delay: square.delay 
        });
        
        tl.to(element, {
          x: driftXPx,
          y: driftYPx,
          opacity: 1, // Full opacity for clear visibility
          duration: square.duration / 2,
          ease: "power1.inOut",
          force3D: false // Expert's recommendation to preserve backdrop-filter
        })
        .to(element, {
          x: 0,
          y: 0,
          opacity: 0.6, // Still visible but more subtle
          duration: square.duration / 2,
          ease: "power1.inOut",
          force3D: false
        });
      }
    });
  }, [squares]); // Rerun animations if squares array (and thus their properties) changes

  return (
    <div ref={containerRef} className="absolute inset-0 isolate">
      {/* Development border to visualize container bounds */}
      {/* {process.env.NODE_ENV === 'development' && (
        <div className="absolute inset-0 border-2 border-dashed border-blue-300 opacity-30 pointer-events-none"></div>
      )} */}
      {squares.map((square) => {
        const { id, topPx, leftPx, squareSizePx, zIndex, color, centerTopPx, centerLeftPx } = square;

        return (
          <Fragment key={id}>
            <div
              data-square-id={id}
              className="absolute backdrop-blur-md will-change-[transform,backdrop-filter]"
              style={{ 
                width: `${squareSizePx}px`,
                height: `${squareSizePx}px`,
                top: `${topPx}px`,
                left: `${leftPx}px`,
                zIndex,
                backgroundColor: `${color}60`, // 37% opacity for better visibility
                opacity: 0.8 // Start more visible, GSAP will animate this
                // All percentage-based sizing relative to container
              }}
            />
            {/* Debug: Show center point in development */}
            {/* {process.env.NODE_ENV === 'development' && (
              <div
                className="absolute w-1 h-1 bg-red-500 pointer-events-none"
                style={{
                  top: `${centerTopPx}px`,
                  left: `${centerLeftPx}px`,
                  zIndex: zIndex + 100,
                  transform: 'translate(-50%, -50%)' // Center the dot on the center point
                }}
              />
            )} */}
          </Fragment>
        );
      })}
    </div>
  );
};

export default AnimatedSquares;