// /src/components/CategoryFilter.js
import React, { useState, useEffect } from "react";

function CategoryFilter({ categories, activeCategory, onSelectCategory }) {
  const [showFilter, setShowFilter] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setShowFilter(window.scrollY >= (window.innerHeight - 500));
    };
    window.addEventListener("scroll", handleScroll);
    // initial check
    handleScroll();
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  return (
    <div
  className={`
    sticky top-0 z-[100]
    flex justify-center items-center
    w-full h-18
    transition-all duration-500 ease-in-out
    pointer-events-none
    ${showFilter ? 'opacity-100' : 'opacity-0'}
  `}
>
  {/* No need for spacers to capture clicks */}
  <div className="relative flex flex-wrap gap-x-6 gap-y-3 justify-center pointer-events-auto">
    {categories.map((cat) => (
      <button
        key={cat}
        onClick={() => onSelectCategory(cat)}
        className={`
          h-6 transition-all duration-300
          ${cat === activeCategory ? 'opacity-100' : 'opacity-60 hover:opacity-80'}
        `}
      >
        {cat}
      </button>
    ))}
  </div>
</div>
  );
}

export default CategoryFilter;