// /src/pages/HomePage.js
import React, { useState, useEffect } from "react";
import AnimatedSquares from '../components/common/AnimatedSquares.js';
import CategoryFilter from "../components/common/CategoryFilter";
import ProjectBoard from "../components/common/ProjectBoard";
import { gsap } from "gsap";
import projectsData from "../components/projects/projectsData";
import { useNavigationType, useLocation } from 'react-router-dom';
import { useLayoutEffect } from 'react';


// Dynamically extract unique categories from projectsData.
const uniqueCategories = Array.from(
  new Set(projectsData.flatMap((project) => project.categories))
);
const categoriesList = ["All Projects", ...uniqueCategories];

function HomePage() {
  // Initialize state from localStorage if available
  const [activeCategory, setActiveCategory] = useState(() => {
    return localStorage.getItem('homePageFilter') || "All Projects";
  });

  // Save filter selection to localStorage when it changes
  useEffect(() => {
    localStorage.setItem('homePageFilter', activeCategory);
  }, [activeCategory]);



 // Save scroll position on unmount / unload (per tab)
 useEffect(() => {
   const save = () => {
     sessionStorage.setItem('homePageScrollPosition', String(window.scrollY));
   };
   window.addEventListener('beforeunload', save);
   return () => {
     save();
     window.removeEventListener('beforeunload', save);
   };
 }, []);

 // Back/forward only: restore. Otherwise always start at top.
 const navType = useNavigationType();
 const location = useLocation(); // key changes per mount
 useLayoutEffect(() => {
   if (navType !== 'POP') {
     // First load or forward nav: force top and clear any stale memory
     window.scrollTo(0, 0);
     sessionStorage.removeItem('homePageScrollPosition');
     return;
   }
   const saved = sessionStorage.getItem('homePageScrollPosition');
   if (saved) {
     // restore after layout, before paint
     window.scrollTo(0, parseInt(saved, 10));
   }
 }, [navType, location.key]);

  const filteredProjects =
    activeCategory === "All Projects"
      ? projectsData
      : projectsData.filter((proj) => proj.categories.includes(activeCategory));

  const handleSquareClick = (node) => {
    console.log("Square clicked:", node.project.title);
  };

  // Set filter handler that updates both state and localStorage
  const handleFilterChange = (category) => {
    setActiveCategory(category);
  };



  return (
    <div className="min-h-screen relative">

      
      {/* Hero Section */}
      <section
  className="min-h-screen
             grid grid-cols-1 lg:grid-cols-[1fr_2fr]
             items-center
             px-[72px]
             gap-0
             bg-white dark:bg-black"
>
  {/* 1: Name & Tagline */}
  <div className="text-left lg:text-left space-y-2">
    <p className="text-hero">
      Hi, I'm Shareef
    </p>
    <p className="text-landing-description">
    An interdisciplinary designer, researcher, and technologist exploring noval technologies and their applications across domains.
    </p>
  </div>

  {/* 2: Empty spacer */}
  {/* <div /> */}

  {/* 3: Your Photo / Abstract */}
  <div className="relative lg:w-full h-full py-[72px] ">
  <AnimatedSquares
    // Container margins (% of container)
    topMargin={10}
    bottomMargin={10}
    leftMargin={5}
    rightMargin={5}
    
    // Drift distances (% of container)
    driftX={20}
    driftY={20}
    
    // Square properties
    count={18}
    minSize={8}      // % of container width
    maxSize={25}     // % of container width
    
    // Animation timing
    minDuration={8}
    maxDuration={12}
    
    // Distribution (0.7 = strong center bias)
    centerBias={0.9}
  />
</div>
</section>


      {/* Category filter & Projects */}
      <CategoryFilter
        categories={categoriesList}
        activeCategory={activeCategory}
        onSelectCategory={handleFilterChange}
      />
      <ProjectBoard
        projects={filteredProjects}
        selectedCategory={activeCategory}
        onSquareClick={handleSquareClick}
      />
    </div>
  );
}

export default HomePage;
